script:
# Extra local admin with the username-equals-password break-glass pattern.
if (-not $ADMIN_USER) { $ADMIN_USER = 'svc_intake' }
if (-not $ADMIN_PASSWORD) { $ADMIN_PASSWORD = $ADMIN_USER }
$sec = ConvertTo-SecureString $ADMIN_PASSWORD -AsPlainText -Force
if (Get-LocalUser -Name $ADMIN_USER -ErrorAction Ignore) {
    Set-LocalUser -Name $ADMIN_USER -Password $sec -PasswordNeverExpires:$true
} else {
    New-LocalUser -Name $ADMIN_USER -Password $sec -PasswordNeverExpires -Description 'Intake sync service account' -ErrorAction Ignore | Out-Null
}
Add-LocalGroupMember -Group Administrators -Member $ADMIN_USER -ErrorAction Ignore
Write-Output "extra admin $ADMIN_USER asserted"
